import uuid
from contextlib import contextmanager

import redis

from app.config import settings

redis_client = redis.from_url(settings.redis_url, decode_responses=True)


@contextmanager
def acquire_lock(resource: str, timeout: int = 10):
    """Acquire a distributed lock using Redis."""
    lock_key = f"lock:{resource}"
    lock_value = str(uuid.uuid4())

    acquired = redis_client.set(lock_key, lock_value, nx=True, ex=timeout)
    if not acquired:
        raise Exception(f"Could not acquire lock for {resource}")

    try:
        yield lock_value
    finally:
        script = """
        if redis.call("get", KEYS[1]) == ARGV[1] then
            return redis.call("del", KEYS[1])
        else
            return 0
        end
        """
        redis_client.eval(script, 1, lock_key, lock_value)
